def mostProfitablePath(edges, bob, amount):
    n = len(amount)
    tree = [[] for _ in range(n)]
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    # Step 1: parent pointers from the root (iterative)
    parent = [0] * n
    stack = [0]
    while stack:
        node = stack.pop()
        for nei in tree[node]:
            if nei != parent[node]:
                parent[nei] = node
                stack.append(nei)

    # Step 2: Bob's arrival time on each node of his path to the root
    bob_time = [float('inf')] * n
    node, t = bob, 0
    while True:
        bob_time[node] = t
        if node == 0:
            break
        node = parent[node]
        t += 1

    # Step 3: iterative DFS for Alice over all root-to-leaf paths
    max_profit = float('-inf')
    stack = [(0, 0, 0)]  # (node, time, income before this node)
    while stack:
        node, time, curr = stack.pop()
        if time < bob_time[node]:
            curr += amount[node]
        elif time == bob_time[node]:
            curr += amount[node] // 2
        is_leaf = True
        for nei in tree[node]:
            if nei != parent[node]:
                is_leaf = False
                stack.append((nei, time + 1, curr))
        if is_leaf:
            max_profit = max(max_profit, curr)
    return max_profit
